form-profile:
'use client';

import { useState } from 'react';
import { Controller, useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Button } from '@/components/ui/button';
import {
  Field,
  FieldLabel,
  FieldDescription,
  FieldError,
} from '@/components/ui/field';
import { Input } from '@/components/ui/input';
import { Alert, AlertTitle, AlertDescription } from '@/components/ui/alert';

const profileSchema = z.object({
  displayName: z
    .string()
    .trim()
    .min(2, 'Use at least 2 characters.')
    .max(32, 'Use at most 32 characters.'),
});
type Profile = z.infer<typeof profileSchema>;

export default function FormProfileDemo() {
  const [saved, setSaved] = useState(false);
  const form = useForm<Profile>({
    resolver: zodResolver(profileSchema),
    defaultValues: { displayName: '' },
  });
  async function submit(values: Profile) {
    setSaved(false);
    form.clearErrors('root');
    // Simulated request; "taken" exercises a server-side validation error locally.
    await new Promise((resolve) => setTimeout(resolve, 700));
    if (values.displayName.toLowerCase() === 'taken') {
      form.setError(
        'displayName',
        { type: 'server', message: 'This display name is already taken.' },
        { shouldFocus: true },
      );
      return;
    }
    setSaved(true);
  }
  return (
    <form
      noValidate
      onSubmit={form.handleSubmit(submit)}
      aria-label="Profile form"
      className="grid w-full max-w-sm gap-5"
    >
      <Controller
        name="displayName"
        control={form.control}
        render={({ field, fieldState }) => (
          <Field
            name={field.name}
            invalid={fieldState.invalid}
            dirty={fieldState.isDirty}
            touched={fieldState.isTouched}
          >
            <FieldLabel>Display name</FieldLabel>
            <Input
              {...field}
              onChange={(event) => {
                field.onChange(event);
                setSaved(false);
              }}
              aria-invalid={fieldState.invalid}
              autoComplete="nickname"
              readOnly={form.formState.isSubmitting}
            />
            <FieldDescription>
              2–32 characters. Try “taken” to simulate a server error.
            </FieldDescription>
            {fieldState.error && (
              <FieldError match>{fieldState.error.message}</FieldError>
            )}
          </Field>
        )}
      />
      <div className="flex flex-wrap gap-3">
        <Button
          type="submit"
          variant="primary"
          loading={form.formState.isSubmitting}
        >
          Save profile
        </Button>
        <Button
          type="button"
          disabled={form.formState.isSubmitting}
          onClick={() => {
            form.reset();
            setSaved(false);
          }}
        >
          Reset profile
        </Button>
      </div>
      <div role="status">
        {saved && (
          <Alert tone="success">
            <AlertTitle>Profile saved locally</AlertTitle>
            <AlertDescription>
              No account or backend is connected to this demo.
            </AlertDescription>
          </Alert>
        )}
      </div>
    </form>
  );
}

party-settings:
'use client';
import { useId, useState } from 'react';
import { Controller, useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import {
  Field,
  FieldLabel,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldItem,
} from '@/components/ui/field';
import {
  Fieldset,
  FieldsetLegend,
  FieldsetDescription,
} from '@/components/ui/fieldset';
import { CheckboxGroup } from '@/components/ui/checkbox-group';
import { Checkbox } from '@/components/ui/checkbox';
import {
  InputGroup,
  InputGroupInput,
  InputGroupAddon,
  InputGroupText,
} from '@/components/ui/input-group';
import { ButtonGroup } from '@/components/ui/button-group';
import { Button } from '@/components/ui/button';

const schema = z.object({
  name: z.string().trim().min(2, 'Use at least 2 characters.'),
  roles: z.array(z.string()).min(1, 'Choose at least one role.'),
});
type Settings = z.infer<typeof schema>;
const roles = ['top', 'jungle', 'support'];

export default function PartySettingsDemo() {
  const descriptionId = useId();
  const [outcome, setOutcome] = useState('');
  const form = useForm<Settings>({
    resolver: zodResolver(schema),
    defaultValues: { name: 'The night shift', roles: ['support'] },
  });
  async function submit(values: Settings) {
    setOutcome('');
    await new Promise((resolve) => setTimeout(resolve, 700));
    setOutcome(`Saved locally: ${values.name} (${values.roles.join(', ')}).`);
  }
  return (
    <form
      aria-label="Party settings"
      noValidate
      onSubmit={form.handleSubmit(submit)}
      className="w-full max-w-sm"
    >
      <Fieldset
        disabled={form.formState.isSubmitting}
        aria-describedby={descriptionId}
      >
        <FieldsetLegend>Party settings</FieldsetLegend>
        <FieldsetDescription id={descriptionId}>
          These settings stay in this local example.
        </FieldsetDescription>
        <FieldGroup>
          <Controller
            name="name"
            control={form.control}
            render={({ field, fieldState }) => (
              <Field name={field.name} invalid={fieldState.invalid}>
                <FieldLabel>Party display name</FieldLabel>
                <InputGroup>
                  <InputGroupInput
                    {...field}
                    aria-invalid={fieldState.invalid}
                  />
                  <InputGroupAddon>
                    <InputGroupText>#</InputGroupText>
                  </InputGroupAddon>
                </InputGroup>
                <FieldDescription>
                  Use a short, recognizable name.
                </FieldDescription>
                {fieldState.error && (
                  <FieldError match>{fieldState.error.message}</FieldError>
                )}
              </Field>
            )}
          />
          <Controller
            name="roles"
            control={form.control}
            render={({ field, fieldState }) => (
              <Field name={field.name} invalid={fieldState.invalid}>
                <FieldLabel nativeLabel={false}>Party roles</FieldLabel>
                <CheckboxGroup
                  value={field.value}
                  onValueChange={field.onChange}
                  allValues={roles}
                >
                  <FieldItem>
                    <FieldLabel className="hx-checkbox-label">
                      <Checkbox parent /> Select all party roles
                    </FieldLabel>
                  </FieldItem>
                  {roles.map((role) => (
                    <FieldItem key={role}>
                      <FieldLabel className="hx-checkbox-label">
                        <Checkbox value={role} /> {role}
                      </FieldLabel>
                    </FieldItem>
                  ))}
                </CheckboxGroup>
                {fieldState.error && (
                  <FieldError match>{fieldState.error.message}</FieldError>
                )}
              </Field>
            )}
          />
          <ButtonGroup aria-label="Party settings actions">
            <Button
              type="submit"
              variant="primary"
              loading={form.formState.isSubmitting}
            >
              Save party
            </Button>
            <Button
              type="button"
              onClick={() => {
                form.reset();
                setOutcome('');
              }}
            >
              Reset party
            </Button>
          </ButtonGroup>
          <p role="status" className="text-hx-sm text-hx-muted-foreground">
            {outcome}
          </p>
        </FieldGroup>
      </Fieldset>
    </form>
  );
}
